//! Minimal runtime string lookup for the zellij-zh-cn localization patches.
//!
//! The translation catalog is generated by `tools/zhcn.py gen-rust` from
//! `i18n/zh-CN.toml` into `src/catalog_generated.rs` (gitignored). Lookup keys
//! are the English originals; anything missing falls back to English.

use std::sync::OnceLock;

// The real catalog is generated by `tools/zhcn.py gen-rust` into
// `src/catalog_generated.rs` (gitignored); build.rs copies it to OUT_DIR or
// emits an empty table. Unit tests use a small built-in table instead so
// `cargo test` works without the generated file.
#[cfg(not(test))]
include!(concat!(env!("OUT_DIR"), "/catalog_generated.rs"));

#[cfg(test)]
static CATALOG: &[(&str, &str)] = &[
    ("Cancel", "取消"),
    (
        "Error {status} connecting to server.",
        "连接服务器出错（{status}）。",
    ),
    ("SESSION (short)", "会"),
];

/// Supported interface languages.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lang {
    En,
    ZhCn,
}

/// The language selected for this process, resolved once and cached.
///
/// The first environment variable that is set and non-empty decides, in this
/// order: `ZELLIJ_LANG`, `LC_ALL`, `LC_MESSAGES`, `LANG`. A value starting with
/// "zh" (case-insensitive) selects `zh-CN`, anything else English.
pub fn lang() -> Lang {
    static LANG: OnceLock<Lang> = OnceLock::new();
    *LANG.get_or_init(|| {
        for key in ["ZELLIJ_LANG", "LC_ALL", "LC_MESSAGES", "LANG"] {
            if let Ok(value) = std::env::var(key) {
                if !value.is_empty() {
                    return lang_from(Some(&value));
                }
            }
        }
        Lang::En
    })
}

/// Map a raw environment value to a language; exposed for tests.
pub fn lang_from(value: Option<&str>) -> Lang {
    match value {
        Some(v) if v.to_lowercase().starts_with("zh") => Lang::ZhCn,
        _ => Lang::En,
    }
}

/// Translate `en` (the English original used as the catalog key). Returns `en`
/// unchanged when the selected language is English or no translation exists.
pub fn tr(en: &'static str) -> &'static str {
    if lang() == Lang::En {
        return en;
    }
    tr_for(lang(), en)
}

fn tr_for(lang: Lang, en: &'static str) -> &'static str {
    if lang == Lang::En {
        return en;
    }
    match CATALOG.binary_search_by(|(key, _)| key.cmp(&en)) {
        Ok(index) => CATALOG[index].1,
        Err(_) => en,
    }
}

/// Look up the catalog by `key` (usually a fuller English phrase) while
/// displaying `en_fallback` when the selected language is English or the key
/// is missing. Use this when two different UI strings share the same English
/// text (e.g. the status-bar short labels "Se" for Search and Session), so
/// each context can get its own translation without changing the English UI.
pub fn tr_ctx(key: &'static str, en_fallback: &'static str) -> &'static str {
    tr_ctx_for(lang(), key, en_fallback)
}

fn tr_ctx_for(lang: Lang, key: &'static str, en_fallback: &'static str) -> &'static str {
    if lang == Lang::En {
        return en_fallback;
    }
    match tr_for(lang, key) {
        translated if translated != key => translated,
        _ => en_fallback,
    }
}

/// Translate `en`, then substitute every `{name}` placeholder with the matching
/// entry from `args`. Placeholders without a matching argument are left as-is.
/// Look up a translation for a runtime string (e.g. a label from user
/// config). Returns the translation, or `text` unchanged when English or
/// missing. Unlike [`tr`] this does not require a `&'static` key.
pub fn tr_dyn(text: &str) -> String {
    match tr_for_dyn(lang(), text) {
        Some(v) => v.to_owned(),
        None => text.to_owned(),
    }
}

fn tr_for_dyn(lang: Lang, text: &str) -> Option<&'static str> {
    if lang == Lang::En {
        return None;
    }
    CATALOG
        .binary_search_by(|(key, _)| (*key).cmp(text))
        .ok()
        .map(|index| CATALOG[index].1)
}

pub fn trf(en: &'static str, args: &[(&str, &str)]) -> String {
    trf_for(lang(), en, args)
}

fn trf_for(lang: Lang, en: &'static str, args: &[(&str, &str)]) -> String {
    let mut text = tr_for(lang, en).to_string();
    for (name, value) in args {
        text = text.replace(&format!("{{{}}}", name), value);
    }
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lang_from_detects_chinese() {
        assert_eq!(lang_from(Some("zh_CN.UTF-8")), Lang::ZhCn);
        assert_eq!(lang_from(Some("zh")), Lang::ZhCn);
        assert_eq!(lang_from(Some("ZH-TW")), Lang::ZhCn);
        assert_eq!(lang_from(Some("en_US.UTF-8")), Lang::En);
        assert_eq!(lang_from(Some("C")), Lang::En);
        assert_eq!(lang_from(Some("")), Lang::En);
        assert_eq!(lang_from(None), Lang::En);
    }

    #[test]
    fn missing_keys_fall_back_to_english() {
        assert_eq!(
            tr_for(Lang::ZhCn, "no such catalog key 0123456789"),
            "no such catalog key 0123456789"
        );
        assert_eq!(tr_for(Lang::En, "Cancel"), "Cancel");
    }

    #[test]
    fn known_key_translates_under_zh() {
        assert_eq!(tr_for(Lang::ZhCn, "Cancel"), "取消");
    }

    #[test]
    fn tr_ctx_disambiguates_shared_english() {
        assert_eq!(tr_ctx_for(Lang::En, "SESSION (short)", "Se"), "Se");
        assert_eq!(tr_ctx_for(Lang::ZhCn, "SESSION (short)", "Se"), "会");
        assert_eq!(tr_ctx_for(Lang::ZhCn, "MISSING (short)", "Mi"), "Mi");
    }

    #[test]
    fn trf_substitutes_named_placeholders() {
        assert_eq!(
            trf_for(
                Lang::ZhCn,
                "Error {status} connecting to server.",
                &[("status", "500")]
            ),
            "连接服务器出错（500）。"
        );
    }

    #[test]
    fn trf_leaves_unmatched_placeholders() {
        assert_eq!(
            trf_for(Lang::ZhCn, "no such {thing} key 987", &[]),
            "no such {thing} key 987"
        );
    }
}
